if (mcopy(ms, p, m->type, 0, s, offset, nbytes, m) == -1)
                        return -1;
                ms->offset = offset;

                if ((ms->flags & MAGIC_DEBUG) != 0) {
                        mdebug(offset, (char *)(void *)p,
                            sizeof(union VALUETYPE));
#ifndef COMPILE_ONLY
                        file_mdump(m);
#endif
                }
        }

        /* Verify we have enough data to match magic type */
        switch (m->type) {
        case FILE_BYTE:
                if (OFFSET_OOB(nbytes, offset, 1))
                        return 0;
                break;

        case FILE_SHORT:
        case FILE_BESHORT:
        case FILE_LESHORT:
                if (OFFSET_OOB(nbytes, offset, 2))
                        return 0;
                break;

        case FILE_LONG:
        case FILE_BELONG:
        case FILE_LELONG:
        case FILE_MELONG:
        case FILE_DATE:
        case FILE_BEDATE:
        case FILE_LEDATE:
        case FILE_MEDATE:
        case FILE_LDATE:
        case FILE_BELDATE:
        case FILE_LELDATE:
        case FILE_MELDATE:
        case FILE_FLOAT:
        case FILE_BEFLOAT:
        case FILE_LEFLOAT:
                if (OFFSET_OOB(nbytes, offset, 4))
                        return 0;
                break;

        case FILE_DOUBLE:
        case FILE_BEDOUBLE:
        case FILE_LEDOUBLE:
                if (OFFSET_OOB(nbytes, offset, 8))
                        return 0;
                break;

        case FILE_STRING:
        case FILE_PSTRING:
        case FILE_SEARCH:
                if (OFFSET_OOB(nbytes, offset, m->vallen))
                        return 0;
                break;

        case FILE_REGEX:
                if (nbytes < offset)
                        return 0;
                break;

        case FILE_INDIRECT:
                if (m->str_flags & INDIRECT_RELATIVE)
                        offset += CAST(uint32_t, o);
                if (offset == 0)
                        return 0;

                if (nbytes < offset)
                        return 0;

                if ((pb = file_push_buffer(ms)) == NULL)
                        return -1;

                (*indir_count)++;
                rv = file_softmagic(ms, s + offset, nbytes - offset,
                    indir_count, name_count, BINTEST, text);

                if ((ms->flags & MAGIC_DEBUG) != 0)
                        fprintf(stderr, "indirect @offs=%u[%d]\n", offset, rv);

                rbuf = file_pop_buffer(ms, pb);
                if (rbuf == NULL && ms->event_flags & EVENT_HAD_ERR)
                        return -1;
